import http from "node:http";
function main(): void {
  const s = http.createServer((req, res) => {
    res.writeHead(201, { "Content-Type": "text/plain", "X-N": 5 });
    res.end("hi");
  });
  s.listen(0, () => {
    const port = (s.address() as any).port;
    http.get({ port }, (res) => {
      let d = "";
      res.on("data", (c) => (d += c));
      res.on("end", () => {
        console.log(res.statusCode, res.headers["content-type"], res.headers["x-n"], d);
        s.close();
      });
    });
  });
}
